        if (mm || (pof && nums.length >= 2)) { let a2, b2; if (mm) { if (/is what percent/.test(mm[0])) { a2 = nm(mm[1]); b2 = nm(mm[2]); } else { b2 = nm(mm[1]); a2 = nm(mm[2]); } } else { const v = nums.map(q => q.v); if (pyield) { const th = nums.find(q => /theoretical|expected|maximum/.test(q.before.slice(-40))); b2 = th ? th.v : Math.max(...v); a2 = v.find(x => x !== b2); } else { a2 = Math.min(v[0], v[1]); b2 = Math.max(v[0], v[1]); const of = lt.match(/(\d[\d.,]*)[^\d]{0,40}?,?\s*(\d[\d.,]*)\s*of (them|which|those)/); if (of) { b2 = nm(of[1]); a2 = nm(of[2]); } } }
          const pp = a2 / b2 * 100; return res({ type: "percent", given: [{ label: "Part", value: a2, unit: "" }, { label: "Whole", value: b2, unit: "" }], answers: [{ label: pyield ? "Percent yield" : "Percentage", text: fmt(pp) + "%", value: pp }], steps: [{ title: "Part ÷ whole", lines: [fmt(a2) + " ÷ " + fmt(b2) + " = " + fmt(a2 / b2)] }, { title: "× 100 to make a percent", lines: [fmt(a2 / b2) + " × 100 = " + fmt(pp) + "%"] }], idea: pyield ? "Percent yield = what you actually got ÷ the most you could get × 100." : "A percentage is the part out of every 100 of the whole.", alt: "Make a fraction " + fmt(a2) + "/" + fmt(b2) + " and scale it to have 100 on the bottom.", mistakes: ["Divide the part by the whole, not the other way round."], draw: { kind: "bars", P: b2, F: a2, p: pp, down: true, mode: "of" }, twin() { const W2 = rnd(4, 40) * 5, p2 = rnd(1, 19) * 5; const pt = W2 * p2 / 100; return { q: "What percent of " + W2 + " is " + pt + "?", ans: p2, ansText: p2 + "%", check: s => close(firstNum(s), p2) }; } }); }
