  sp({ id: "resistors", subj: "physics", name: "Series & parallel resistors", icon: "🔌", draw: "resnet", kw: ["series", "parallel", "resistors", "combined resistance", "total resistance", "equivalent resistance"],
    ex: "Resistors of 4 Ω, 6 Ω and 12 Ω are connected in parallel to a 12 V battery. Find the total resistance and current.",
    detect(t) { const q = SV.quantities(t).filter(x => x.dim === "resistance"); return q.length >= 2 && /series|parallel/.test(t.toLowerCase()) ? 48 : 0; },
    solve(t, over) { const lt = t.toLowerCase(); let Rs = SV.quantities(t).filter(x => x.dim === "resistance").map(x => SV.conv(x.v, x.unit, "Ω")); const Vq = SV.quantities(t).find(x => x.dim === "voltage"); let V = Vq ? SV.conv(Vq.v, Vq.unit, "V") : null; if (over && over.vals) { Rs = Rs.map((r, i) => over.vals["R" + i] ?? r); if (V != null) V = over.vals.V; }
      const par = /parallel/.test(lt) && !/series/.test(lt.slice(0, lt.indexOf("parallel"))); const Rt = par ? 1 / Rs.reduce((a, r) => a + 1 / r, 0) : Rs.reduce((a, b) => a + b, 0);
      const steps = [par ? { title: "Parallel: add the 1/R's", lines: ["1/R = " + Rs.map(r => "1/" + fmt(r)).join(" + ") + " = " + fmt(1 / Rt), "R = 1 ÷ " + fmt(1 / Rt) + " = " + fmtU(Rt, "Ω")] } : { title: "Series: just add them", lines: ["R = " + Rs.map(fmt).join(" + ") + " = " + fmtU(Rt, "Ω")] }];
      const answers = [{ label: "Total resistance", text: fmtU(Rt, "Ω"), value: Rt }];
      if (V != null) { const I = V / Rt; steps.push({ title: "Total current (Ohm's law)", lines: ["I = V ÷ R = " + fmt(V) + " ÷ " + fmt(Rt) + " = " + fmtU(I, "A")] }); answers.push({ label: "Total current", text: fmtU(I, "A"), value: I });
        steps.push({ title: par ? "Current in each branch (same voltage)" : "Voltage across each (same current)", lines: Rs.map((r, i) => par ? "R" + (i + 1) + ": " + fmt(V) + " ÷ " + fmt(r) + " = " + fmtU(V / r, "A") : "R" + (i + 1) + ": " + fmt(I) + " × " + fmt(r) + " = " + fmtU(I * r, "V")) }); answers.push({ label: "Power", text: fmtU(V * I, "W"), value: V * I }); }
      return res({ type: "resistors", given: Rs.map((r, i) => ({ label: "R" + (i + 1), value: r, unit: "Ω", src: "read" })).concat(V != null ? [{ label: "Voltage", value: V, unit: "V", src: "read" }] : []), answers, steps,
        idea: par ? "In parallel the current has several paths, so the total resistance is LESS than the smallest resistor." : "In series the current has one path through every resistor, so the resistances add up.", alt: par && Rs.length === 2 ? "Two in parallel: R = (R₁ × R₂) ÷ (R₁ + R₂) = " + fmt(Rs[0] * Rs[1]) + " ÷ " + fmt(Rs[0] + Rs[1]) + " = " + fmt(Rt) + " Ω." : "Check: series total is always bigger than any single resistor.",
        mistakes: ["Parallel: don't forget the final 1 ÷ at the end.", "kΩ → × 1000."], draw: { kind: "resnet", Rs, par, V, Rt }, sliders: Rs.map((r, i) => ({ id: "R" + i, label: "R" + (i + 1), unit: "Ω", value: r, min: 1, max: r * 3, step: 1 })).concat(V != null ? [{ id: "V", label: "Voltage", unit: "V", value: V, min: 0, max: V * 2, step: 0.5 }] : []),
        twin() { const a = rnd(2, 12), b = rnd(2, 12), p2 = Math.random() < .5; const ans = p2 ? a * b / (a + b) : a + b; return { q: "Two resistors of " + a + " Ω and " + b + " Ω are connected in " + (p2 ? "parallel" : "series") + ". Find the total resistance.", ans, ansText: fmtU(ans, "Ω"), check: s => close(firstNum(s), ans) }; } }); } });

