      let actG = null; if (/percent(age)? yield/i.test(t) && giv.length >= 2) { actG = giv.find(g => b.R.some(r => r.raw === g.s.f)); if (actG) giv.splice(giv.indexOf(actG), 1); }
      if (!giv.length) return res({ ok: false });
      const q = T2.slice(T2.search(/how many|what mass|calculate|find|what volume|how much|which|determine/i)); const hasF = (s, f) => new RegExp("(?<![A-Za-z0-9(])" + f.replace(/[()]/g, "\\$&") + "(?![a-z0-9])").exec(s); let tgt = actG ? actG.s : sp2.filter(s => !giv.some(g => g.s === s) && hasF(q, s.f)).sort((a, b) => hasF(q, a.f).index - hasF(q, b.f).index)[0] || sp2.filter(s => !giv.some(g => g.s === s) && b.R.some(r => r.raw === s.f))[0]; const wantMol = /how many moles|moles of|number of moles/i.test(q), wantVol = /volume|litres|liters|dm3|dm³/i.test(q);
      const steps = [{ title: "Balanced equation", lines: [b.text] }]; let lim = giv[0];
