      const answers = []; if (giv.length >= 2) answers.push({ label: "Limiting reactant", text: CH.pretty(lim.s.f), value: 0 });
      if (tgt) { const nT = lim.n * tgt.k / lim.s.k; steps.push({ title: "Use the ratio from the equation", lines: [CH.pretty(lim.s.f) + " : " + CH.pretty(tgt.f) + " = " + lim.s.k + " : " + tgt.k, "n(" + CH.pretty(tgt.f) + ") = " + fmt(lim.n) + " × " + tgt.k + "/" + lim.s.k + " = " + fmt(nT) + " mol"] });
        const mT = nT * tgt.M; if (wantMol) answers.unshift({ label: "Moles of " + CH.pretty(tgt.f), text: fmt(nT) + " mol", value: nT }); else if (wantVol) { answers.unshift({ label: "Volume of " + CH.pretty(tgt.f) + " (room temperature, 24 L/mol)", text: fmt(nT * 24) + " L", value: nT * 24 }); steps.push({ title: "Gas volume", lines: ["V = n × 24 L = " + fmt(nT * 24) + " L"] }); } else { answers.unshift({ label: "Mass of " + CH.pretty(tgt.f), text: fmt(mT) + " g", value: mT }); steps.push({ title: "Back to grams", lines: ["m = n × M = " + fmt(nT) + " × " + fmt(tgt.M) + " = " + fmt(mT) + " g"] }); }
        if (giv.length >= 2) { const ex = giv.find(g => g !== lim); const used = lim.n * ex.s.k / lim.s.k; answers.push({ label: CH.pretty(ex.s.f) + " left over", text: fmt((ex.n - used) * ex.s.M) + " g", value: (ex.n - used) * ex.s.M }); }
        const ym = lt0.match(/actual yield (?:is|was|of)?\s*(\d[\d.]*)\s*g|(\d[\d.]*)\s*g (?:is|was|were) (?:actually )?(?:obtained|produced|collected|made)/); if (actG && !ym) { const act = SV.conv(actG.v, actG.u, "g"); answers.unshift({ label: "Percentage yield", text: fmt(act / mT * 100) + "%", value: act / mT * 100 }); steps.push({ title: "Percentage yield", lines: ["actual ÷ theoretical × 100 = " + fmt(act) + " ÷ " + fmt(mT) + " × 100 = " + fmt(act / mT * 100) + "%"] }); }
        if (ym) { const act = +(ym[1] || ym[2]); answers.push({ label: "Percentage yield", text: fmt(act / mT * 100) + "%", value: act / mT * 100 }); steps.push({ title: "Percentage yield", lines: ["actual ÷ theoretical × 100 = " + act + " ÷ " + fmt(mT) + " × 100 = " + fmt(act / mT * 100) + "%"] }); } }
